head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    var id = "tab1";
    //var url = "";
	var url = "./tab_child1.xml";
    var tabOpt = {
        label: "탭1",
        title: "타이틀1",
        openAction: "select"
        /*
                    ,closable: true
                    ,disabled: false
                    ,tabWidth: ""
                    ,"class": ""
                    ,style: ""
                    ,activeTabClass: ""
                    ,disabledTabClass: ""
                    ,selectedImage: ""
                    ,defaultImage: ""
                    ,hoverImage: ""
                    ,tabType: "text"
                    ,selectedClass: ""
                    ,hoverClass: ""
                    //,addTabIndex: ""
                    ,useATagBtn: ""*/
    };
    var contOpt = {
        src: url,
        wframe: true,
        alwaysDraw: true,
        style: "",
        name: id,
        title: "타이틀11"
    };
    tabControl1.addTab(id, tabOpt, contOpt);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('wq_uuid_2_iframe_0').outerHTML.indexOf(' ;') == -1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
